// === Tab: sketch.js ===
// Reaction-Diffusion with Logo Interaction
// © 2024-05-15 by Zaron Chen, modified
// Licensed under the MIT License.

import { mountFlex } from "https://cdn.jsdelivr.net/npm/p5.flex@0.2.0/src/p5.flex.mjs"
import { BLUR, UNSHARP, VERT } from "./shader.js"

p5.disableFriendlyErrors = true
mountFlex(p5)

new p5((p) => {
  const [WIDTH, HEIGHT] = [1920, 1080]
  const PIXEL_DENSITY = 1
  const TEXEL_SIZE = [1 / (WIDTH * PIXEL_DENSITY), 1 / (HEIGHT * PIXEL_DENSITY)]
  const RENDERER = p.WEBGL

  let cnv, gfx, img
  let BlurPass, UnsharpPass
  let logoScale = 0.5
  let reactionSpeed = 1
  let diffusionStrength = 1

  p.preload = () => (img = p.loadImage("https://openprocessing.org/sketch/2495760/files/unolab-logo-png.png"))

  p.setup = () => {
    cnv = p.createCanvas(WIDTH, HEIGHT, RENDERER)
    p.flex({ container: { padding: "20px" }, canvas: { fit: p.SCALE_DOWN } })
    p.pixelDensity(PIXEL_DENSITY)

    gfx = p.createGraphics(WIDTH, HEIGHT, p.WEBGL)

    BlurPass = p.createShader(VERT, BLUR)
    UnsharpPass = p.createShader(VERT, UNSHARP)

    RENDERER === p.WEBGL && p.rectMode(p.CENTER)
    RENDERER === p.WEBGL && p.imageMode(p.CENTER)

    p.background(0)
    p.noStroke()
    gfx.noStroke()

    createUI()
  }

  p.draw = () => {
    p.background(0)
    drawLogo()
    ReactionDiffusion()
  }

  const drawLogo = () => {
    p.push()
    RENDERER === p.WEBGL && p.translate(-WIDTH / 2, -HEIGHT / 2)
    const logoWidth = WIDTH * logoScale
    const logoHeight = HEIGHT * logoScale
    p.image(img, WIDTH / 2, HEIGHT / 2, logoWidth, logoHeight)
    p.pop()
  }

  const ReactionDiffusion = () => {
    gfx.shader(BlurPass)
    BlurPass.setUniform("texelSize", TEXEL_SIZE)
    BlurPass.setUniform("tex0", cnv)
    BlurPass.setUniform("direction", [1 * reactionSpeed, 0])
    gfx.quad(-1, 1, 1, 1, 1, -1, -1, -1)

    gfx.shader(BlurPass)
    BlurPass.setUniform("texelSize", TEXEL_SIZE)
    BlurPass.setUniform("tex0", gfx)
    BlurPass.setUniform("direction", [0, 1 * reactionSpeed])
    gfx.quad(-1, 1, 1, 1, 1, -1, -1, -1)

    gfx.shader(UnsharpPass)
    UnsharpPass.setUniform("texelSize", TEXEL_SIZE)
    UnsharpPass.setUniform("tex0", gfx)
    UnsharpPass.setUniform("strength", diffusionStrength)
    gfx.quad(-1, 1, 1, 1, 1, -1, -1, -1)

    p.image(gfx, 0, 0)
  }

  const createUI = () => {
    const logoSlider = p.createSlider(0.1, 1, logoScale, 0.01)
    logoSlider.position(20, 20)
    logoSlider.style("width", "200px")
    logoSlider.input(() => logoScale = logoSlider.value())

    const reactionSlider = p.createSlider(0.1, 3, reactionSpeed, 0.1)
    reactionSlider.position(20, 50)
    reactionSlider.style("width", "200px")
    reactionSlider.input(() => reactionSpeed = reactionSlider.value())

    const diffusionSlider = p.createSlider(0.1, 5, diffusionStrength, 0.1)
    diffusionSlider.position(20, 80)
    diffusionSlider.style("width", "200px")
    diffusionSlider.input(() => diffusionStrength = diffusionSlider.value())

    const instructions = p.createDiv("<b>Controls:</b><br>\nScale: Adjust size of logo<br>\nReaction Speed: Adjust animation speed<br>\nDiffusion Strength: Adjust diffusion effect")
    instructions.style("color", "white")
    instructions.position(20, 110)
  }
})


// === Tab: shader.js ===
import * as Shox from "https://cdn.jsdelivr.net/npm/shox@1.2.0/src/Shox.js"

export const BLUR = `#version 300 es
	precision highp float;

	uniform sampler2D tex0;
	uniform vec2 texelSize;
	uniform vec2 direction;

	${Shox.blur(3)}

	in vec2 vTexCoord;
	out vec4 fragColor;
	void main() { fragColor = blur(vTexCoord, tex0, texelSize, direction); }
`

export const UNSHARP = `#version 300 es
	precision mediump float;

	uniform sampler2D tex0;
	uniform vec2 texelSize;

	${Shox.unsharp}

	in vec2 vTexCoord;
	out vec4 fragColor;
	void main() { fragColor = unsharp(vTexCoord, tex0, texelSize*7., 64.); }
`

export const VERT = `#version 300 es

	in vec4 aPosition;
	in vec2 aTexCoord;

	out vec2 vTexCoord;

	void main() {
		vTexCoord = aTexCoord;
		gl_Position = aPosition;
	}
`


